    facts: [['07', "القدرات الحجزية", "ويشكّل الجدول الزمني، والتوافر، والضيوف دون حجز مسبق، وإحالة الطاولة، وتدفق الضيوف، والطوابق المتعددة النطاق الحالي للمنتجات."], ['03', "التخطيط", "ويدعم الجدول الزمني والجدول الزمني والسياق الأرضي الحي قرارات مختلفة قبل الخدمة وأثناءها."], ['02', "أنواع الوصول", "ويمكن التعامل مع عمليات الحجز المؤكدة والضيوف دون حجز مسبق دون فقدان الصورة الأوسع للقدرات."], ["مباشر", "السياق", "وتظل جداول الجلوس مفتوحة ومتاحة ومحجوزة."]],
