    metrics: [["معدل القيد بين القيد", "مقارنة بالحجز المؤكد مع الوافدين الفعليين باستخدام نفس قواعد الإلغاء وعدم العرض."], ["معدل عدم الحضور", "ويتوقع من الأطراف التي لم تصل بعد أو تجزأ حسب الفترة أو المصدر أو الموقع حيثما كان ذلك متاحا."], ["وقت الوصول إلى الغلاف", "قياس الانتظار بين وصول الضيوف والمقاعد المخصصة خلال فترات الخدمة المماثلة."], ["استخدام الجدول ودورانه", "استعراض مدى توافر القدرة وكم تبقى من الطاولات تحت تعاريف المطعم"]],
